import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
REFERENCE = 'https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/understanding-shutter-speed'
# Fields: slug,title,english,category,hook,summary,explanation,pitfall,scene,tags,sourceTitle,sourceUrl
rows = []
def add(id, slug, title, english, category, hook, summary, explanation, pitfall, scene, tags, source_title, source_url):
    row = {'id': id, 'slug': slug, 'title': title, 'english': english, 'category': category,
           'hook': hook, 'summary': summary, 'explanation': explanation, 'pitfall': pitfall,
           'scene': scene, 'tags': tags, 'sourceTitle': source_title, 'sourceUrl': source_url,
           'image': f'assets/posters/{id:02}-{slug}.png'}
    labels = scene.split('标签：', 1)[1] if '标签：' in scene else ''
    row['prompt'] = (
        'Use the attached reference image only for the consistent visual system and poster layout; invent an original scene for this concept. '
        'Create ONE finished Chinese educational comic poster for Xiaohongshu, portrait 3:4, exact 1200x1600 px. '
        'Match the established 概念探险队 collection: The Adventures of Tintin / 丁丁历险记 inspired European ligne claire cartoon, confident clean even-width navy outlines, flat unshaded colors, warm ivory #FFF7E7 paper, navy #17324A, cobalt #3879B8, coral #D85C43, mustard #E8B751 and jade #4F8D78. '
        'Thin navy rectangular frame, generous 7% safe margins, simple precise diagram and small lightly humorous original adventure characters, never any existing Tintin character. No photorealism, 3D, gradients, watercolor, paper distress or dense hatching. '
        'Large dark-navy Simplified Chinese type must be crisp and phone-readable. Keep the exact same hierarchy: small top line; issue/category; large title; one short hook; main explanatory scene occupying about 55%; pale mustard bottom takeaway band; small footer. '
        'Use only these exact Chinese text strings, preserve every character and punctuation, no additional claims or prose: '
        f'top “概念探险队 / 一图搞懂一个概念”; issue “{id:02} · {category}”; title “{title}”; hook “{hook}”; '
        f'diagram labels “{labels}”; bottom “记住这句” and “{summary}”; footer “CONCEPT ATLAS · {id:02}”. '
        f'Illustration: {scene} Make the causal relationship and arrows clear, avoid clutter and tiny text. One poster, one concept.'
    )
    rows.append(row)

add(61,'long-exposure','长曝光','Long Exposure','电影摄影','快门开得够久，夜里的车流就会变成光带。','长时间开着快门，让运动中的光在画面里留下连续轨迹。','长曝光是在较长时间内让相机传感器持续接收光线。静止景物相对清晰，移动的车灯、水流或人群会在曝光期间经过多个位置，于是被记录成光带或模糊影。','它不是把快门速度调快；曝光越久，移动物体通常越容易拖影，也更需要稳定相机。','同一条城市道路对照两格：左边短暂曝光，汽车清晰定格；右边长时间曝光，静止建筑仍清楚，汽车只留下连续的红白灯轨。相机固定在三脚架上。标签：短曝光｜长曝光｜光轨',['摄影','快门','夜景'],'Canon Europe · PowerShot Manual','https://files.canon-europe.com/files/soft40480/Manual/PSA1200_CUG_EN.pdf')
add(62,'golden-hour','黄金时刻','Golden Hour','电影摄影','太阳低一点，脸上的阴影就柔和许多。','日出日落附近，低角度阳光经过更长的大气路径，色调偏暖、阴影较长。','太阳接近地平线时，光线从侧面掠过人物和建筑，明暗层次更明显；经过较厚的大气后，直射光也常显得更暖。摄影师会利用这段时间拍人像和风景。','黄金时刻不是固定的“整整一小时”，实际长短随季节、纬度、地形和天气变化。','同一位行人在正午和日落时各站在街角：正午顶光形成硬短阴影，日落低角度暖光照亮侧脸并拉长地面影子。标签：正午｜低角度｜长阴影',['摄影','自然光','人像'],'Nikon Learn & Explore · Summer photography from dawn to dusk','https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/summer-photography-from-dawn-to-dusk')
add(63,'leading-lines','视觉引导线','Leading Lines','电影摄影','为什么一眼就看向画面深处？','道路、栏杆或光线会把视线沿着画面方向引向主体。','引导线是画面中能带动视线移动的线状元素。平行线在透视中朝远处汇聚，或曲线环绕主体，都能建立方向感和空间层次。','引导线只是构图工具；它不一定是笔直的线，也不保证观众只看一个位置。','火车站台的两条轨道从画面底部向远处汇聚，探险者站在尽头成为视觉落点；旁边对照一张无明显线条的杂乱构图。标签：近处｜汇聚方向｜主体',['摄影','构图','视线'],'Nikon Learn & Explore · 5 easy composition guidelines','https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/5-easy-composition-guidelines')
add(64,'negative-space','负空间构图','Negative Space','电影摄影','留白越多，主体有时反而越醒目。','主体以外的空处也属于构图；它能让主体突出，并表达安静、孤独或方向。','负空间是主体周围相对简洁的区域。它减少周围信息的干扰，也能给视线留出方向和呼吸感，使小主体显得突出。','负空间不是画面里“什么都没有”；颜色、明暗和空白的形状都会影响主体关系。','一张海边插画：小小的黄色雨衣行人站在画面左下，大片干净的浅蓝天空和海面留在右侧，视线朝向空处；对照一张边角都塞满物件的画面。标签：主体｜留白｜视线方向',['摄影','构图','留白'],'Nikon Learn & Explore · 5 easy composition guidelines','https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/5-easy-composition-guidelines')
add(65,'shutter-speed','快门速度','Shutter Speed','电影摄影','雨滴能被冻结，也能变成一条线。','快门时间短，运动更容易定格；时间长，运动更容易留下模糊轨迹。','快门控制传感器接收光线的时长。高速快门把运动切成很短一瞬，低速快门会把物体在这段时间的位置累积到同一张画面。','快门速度同时影响进光量；画面亮度还受光圈、ISO和环境光影响。','同一只跳跃的狗的两幅照片：快门快时空中的水珠清晰悬停；快门慢时水珠和狗爪沿运动方向拖成柔和短线。标签：高速｜定格｜低速｜拖影',['摄影','曝光','运动'],'Nikon Learn & Explore · Understanding shutter speed','https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/understanding-shutter-speed')
add(66,'forced-perspective','强制透视','Forced Perspective','电影摄影','离镜头近的手，能“拿住”远处的太阳。','利用近大远小的视觉规律，让相隔很远的物体看起来接触或改变大小。','强制透视通过安排相机、前景和远景的相对位置，制造不寻常的大小关系。人物在镜头前伸手，远处的建筑或月亮就可能恰好落在手上。','这是视点造成的视觉效果，物体实际大小和距离并没有改变。','相机前方的游客伸出两指，远处橙色太阳正好夹在指尖之间；旁边用俯视小图标出相机、人物和远处太阳的距离。标签：近处｜镜头位置｜远处',['摄影','透视','错觉'],'Canon Europe · PowerShot Manual','https://files.canon-europe.com/files/soft40480/Manual/PSA1200_CUG_EN.pdf')
add(67,'eyeline-match','视线匹配','Eyeline Match','电影摄影','人物看向画外，下一镜头替你揭晓他在看什么。','先给出人物的视线方向，再切到相符位置的对象，观众会把两镜头连起来。','视线匹配是剪辑中的连续性方法：先看到角色看向画外，再看到一个位置和方向相配的对象，让观众理解两者的观看关系。','它是一种镜头连接方式，不等于镜头一定要拍到角色眼睛的特写。','两格电影分镜：第一格人物面向右上看出画外，第二格切到右上方窗台上的猫；用同色视线箭头连起两格。标签：人物视线｜匹配方向｜被看对象',['电影','剪辑','视线'],'Columbia University Film Glossary · Eye-line match','https://filmglossary.ccnmtl.columbia.edu/term/eye-line-match/')

add(68,'offtracking','内轮差','Offtracking','出行交通','大车转弯时，后轮为什么会抄进弯心？','车辆转弯时，后轮走过的轨迹会比前轮更靠近弯心。','内轮差是车辆转弯时前后轮轨迹不重合的现象。轴距越长，转弯半径越小，后轮通常越可能切入前轮内侧的区域。','内轮差区域对任何转弯车辆都可能危险；驾驶员与行人不能只看车头位置。','俯视路口中一辆长卡车向右转弯：前轮沿外侧弧线转，后轮沿更靠近弯心的内侧弧线压过黄色危险区。标签：前轮轨迹｜后轮轨迹｜内侧危险区',['大车','转弯','交通安全'],'FHWA · Truck offtracking','https://www.fhwa.dot.gov/policy/otps/truck/wusr/chap06.cfm')
add(69,'reverse-parking','倒车入库','Reverse Parking','出行交通','方向盘一打，车尾为什么朝另一边摆？','倒车时，车尾会先朝前轮转向的反方向移动，再沿弧线进入车位。','倒车入库要同时观察车尾扫过的空间、车身与车位角度，以及车辆转弯半径。方向盘改变前轮方向后，车头和车尾会走不同轨迹。','车辆尺寸、轴距和转向角不同，不能把一个固定的转向点当成适用于所有车的口诀。','俯视空车位三步图：车身先驶过车位，倒车时车尾沿弧线摆入，两侧后视镜与线保持观察；箭头标出车尾转弯空间。标签：车位｜车尾弧线｜观察盲区',['停车','倒车','驾驶'],'California DMV · Parking','https://www.dmv.ca.gov/portal/handbook/california-driver-handbook/parking/')
add(70,'a-pillar-blind-spot','A柱盲区','A-pillar Blind Spot','出行交通','转弯时，行人可能刚好藏在车窗边框后。','车身前侧的A柱会挡住一部分视线，行人与车辆相对移动时盲区也会变化。','A柱支撑前挡风玻璃。它的宽度、倾角、车速和观察角度会共同影响驾驶员是否看见被遮挡的目标。','不能只转一次头就假定盲区消失；转向前应减速、移动视线并再次观察。','驾驶员视角透过挡风玻璃看路口：粗A柱遮住正在横过斑马线的行人；旁边小图显示驾驶员改变头部位置后，行人从柱子后露出。标签：A柱｜遮挡区｜行人',['驾驶','盲区','行人'],'NHTSA · Vehicle blind zones and mirrors','https://www.nhtsa.gov/sites/nhtsa.gov/files/blindzone.pdf')
add(71,'hydroplaning','水滑现象','Hydroplaning','出行交通','轮胎压不住积水时，方向盘会突然变轻。','轮胎排水不及，水层可能隔开轮胎与路面，让抓地力骤降。','水滑现象会在轮胎无法及时排开路面水时发生。轮胎与路面接触减弱，车辆转向和制动能力可能受到影响。','速度、积水深度、胎面和胎压都会影响风险；水滑时猛打方向或急刹可能更危险。','俯视湿滑道路侧剖面：正常时轮胎纹路把水推向两边并贴住路面；积水变深时水楔抬起轮胎，画出变小的接触区域。标签：排水｜水楔｜抓地力下降',['雨天','轮胎','驾驶'],'NHTSA · Tires and hydroplaning','https://www.nhtsa.gov/vehicle-safety/tires')
add(72,'sightline-blind-spot','视线死角','Sightline Blind Spot','出行交通','停在路口的车和墙，也会替你“藏”住来车。','障碍物遮住的区域里，行人、车辆或自行车可能暂时看不见。','视线死角来自墙角、停放车辆、植被等遮挡物。观察者的位置变化后，被遮住的目标才会逐渐露出。','盲区会随观察位置改变；看见道路的一部分，不代表已经看清整个冲突方向。','街角俯视示意：建筑墙角挡住接近斑马线的自行车，行人沿墙边多走一步后视线越过墙角。标签：遮挡物｜看不见｜移动后看见',['路口','视线','安全'],'FHWA · Pedestrian safety countermeasures','https://highways.dot.gov/safety/pedestrian-bicyclist')
add(73,'following-distance','跟车距离','Following Distance','出行交通','前车突然刹车，留出的距离就是反应时间。','车速越快、路况越差，需要预留的停车空间通常越长。','驾驶员发现危险后要先反应再制动，因此停车总距离包括反应距离和制动距离。跟车过近会让可用于判断和停车的余量变小。','固定秒数是简化的安全提示，不是任何速度、天气和车辆下都够用的保证。','湿路上两辆车同向行驶：前车突然亮起刹车灯，后车的反应距离与制动距离分别画成两个空档；过近的第二例无法停住。标签：反应｜制动｜安全间隔',['跟车','停车距离','安全'],'FMCSA · Following too closely','https://www.fmcsa.dot.gov/safety/driver-safety/cmv-driving-tips-following-too-closely')
add(74,'tire-traction','轮胎抓地力','Tire Traction','出行交通','轮胎再强，也要先碰得到路面。','胎面、路况和轮胎受力一起决定可用抓地力。','轮胎抓地力来自胎面与路面接触时可传递的力，影响转弯、加速和制动。湿滑、冰面、磨损或胎压不当都可能改变表现。','抓地力不是一个固定数值；同时急转向、加速和制动会争用有限的轮胎能力。','俯视轮胎压在干路和湿滑路的对照：干路接触面用短箭头表示转向力，水膜一侧箭头变短并向外滑。标签：接触面｜路况｜可用抓地力',['轮胎','路面','摩擦'],'NHTSA · Tire safety','https://www.nhtsa.gov/vehicle-safety/tires')
add(75,'zipper-merge','拉链式通行','Zipper Merge','出行交通','两条车道轮流并入，比一早挤进一条更顺。','在车道合流点附近交替并入，能更均匀地利用两条车道。','拉链式通行指两条车道接近合流处时，车辆按一辆一辆交替进入共同车道。它让队列分布更均匀，并减少过早并线造成的空隙。','它需要合流处空间和驾驶员配合；请遵守当地标志、道路规则和现场指挥。','两列车辆缓慢行至施工合流点：红车、蓝车在合流处按一红一蓝交替汇入，标清“交替”而非抢道。标签：车道A｜车道B｜一辆一辆',['并道','拥堵','驾驶'],'FHWA · Zipper merge at work zones','https://highways.fhwa.dot.gov/sites/fhwa.dot.gov/files/FHWA-HRT-23-070.pdf')
add(76,'phantom-traffic-jam','幽灵堵车','Phantom Traffic Jam','出行交通','没有事故，也可能凭空堵成一条长龙。','车辆跟得太紧时，小幅刹车会沿车流向后放大成停走波。','高密度车流中，驾驶员的轻微减速可能让后车更明显地刹车，波动逐车传播后，队尾甚至会停下；前方未必有事故或障碍。','交通流波动有多种成因；这不代表每次拥堵都由驾驶员一个动作引起。','俯视环形道路小图：最前车轻踩刹车，后车刹得稍重，形成向队尾扩大的红色停走波；波过后前方道路仍空。标签：轻微减速｜向后放大｜车流波',['拥堵','车流','交通'],'FHWA · Traffic Flow Theory','https://ops.fhwa.dot.gov/publications/fhwahop18013/chap2.htm')
add(77,'elevator-signal','电梯信号变差','Elevator Signal Loss','出行交通','电梯一关门，手机信号为何常掉格？','金属结构和封闭空间会衰减无线电波，接收条件也随位置变化。','手机通过无线电波和基站通信。电梯轿厢的金属结构、墙体遮挡、楼层位置及周边基站覆盖都可能削弱接收信号。','并非每部电梯都会断网；信号表现取决于运营商、建筑材料和附近覆盖。','建筑剖面中的手机信号波：室外基站信号穿过楼体后变弱，金属电梯轿厢内的手机只收到少量波纹；旁边窗边信号较强。标签：基站｜墙体衰减｜电梯轿厢',['手机','无线信号','建筑'],'EUDL · Mobile communication in elevators','https://eudl.eu/doi/10.4108/icst.mobihealth.2014.257410')

add(78,'international-date-line','国际日期变更线','International Date Line','自然与旅行','跨过这条线，日历上的日期会突然变一天。','国际日期变更线附近，东西两侧通常相差一个日历日期。','为了让全球日期与经度大致对应，国际日期变更线沿太平洋曲折延伸。跨线旅行时需要调整日历日期，具体取决于行进方向。','它不是严格笔直的180度经线，会绕开国家和岛屿；也不是任何地方实际时间都差24小时。','太平洋地图中一条曲折虚线，两艘船分处两侧：同一时刻显示星期一和星期二；标出向东和向西跨线时日期的变化。标签：西侧｜变更线｜东侧',['地理','时区','旅行'],'NOAA Ocean Service · International Date Line','https://oceanservice.noaa.gov/facts/international-date-line.html')
add(79,'jet-stream','高空急流','Jet Stream','自然与旅行','飞机遇到高空急流，飞行时间可能不同。','高空急流是对流层高处狭长而快速的风带，会影响天气和航路。','急流多出现在对流层上部、温度差较大的区域。飞机航路若顺风或逆风穿越，地速和飞行时间可能发生变化，航线也会随天气调整。','急流不会让飞机“搭风就必然更省时”；航空公司还需考虑安全、气流和航路限制。','地球弧面上空画一条狭长蓝色高速风带；同一架飞机顺风方向箭头更长、逆风方向更短，地面天气系统随风带移动。标签：高空风带｜顺风｜逆风',['气象','航空','风'],'NOAA JetStream · The Jet Stream','https://www.noaa.gov/jetstream/global/jet-stream')
add(80,'great-circle-route','大圆航线','Great Circle Route','自然与旅行','地图上看着绕远，地球上可能才是直线。','地球表面的最短路径沿大圆弧线，不一定像平面地图上的直线。','大圆是通过球心的平面与球面相交形成的圆。两点间的最短球面路径沿大圆走，因此在常见平面地图上可能显示为向高纬拱起的曲线。','实际航班还要考虑风、空域和安全；最短几何距离不一定就是实际航线。','球形地球上连接两座城市的红色大圆弧，与平面地图上看似直的线作对照；飞机沿球面弧线飞行。标签：球面｜大圆弧｜平面地图',['地理','航线','地图'],'FAA · Aeronautical Information Manual · Great circle','https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap1_section_1.html')
add(81,'mirage','海市蜃楼','Mirage','自然与旅行','公路尽头像有水，走近却什么也没有。','不同温度的空气让光线弯折，远处景物就可能出现在不寻常的位置。','近地面空气温度分层时，不同层的折射率不同，光线会逐渐弯曲。观察者把弯折后的光沿直线反向延伸，便会把景物看成地面上的水或天空中的倒影。','海市蜃楼是真实光路造成的视觉影像，不是地面真的出现了一片水。','热公路的侧面剖视图：地面附近空气分层，天空光线弯向观察者眼睛；眼睛把光线直线追踪，误以为路上有一池天空倒影。标签：冷热空气层｜弯曲光路｜虚像',['光学','天气','视觉'],'WMO International Cloud Atlas · Mirage','https://cloudatlas.wmo.int/en/mirage.html')
add(82,'rip-current','离岸流','Rip Current','自然与旅行','海浪一直往岸上来，水却能沿窄道冲回海里。','水流汇集后可能形成狭窄、快速朝外海移动的离岸流。','波浪把水推向岸边后，水需要回流。某些海岸地形会让回流水集中在较窄通道，形成离岸流；它可能把游泳者带离岸边。','离岸流不是“把人往下吸”的暗流；遇到时尽量保持漂浮并平行岸边游出水流，再求助。','海滩俯视图：白色波浪铺向岸边，回流水汇集成一条窄蓝带向外海；游客漂浮并横向游向两侧较弱水域。标签：来浪｜汇流水道｜离岸流',['海滩','游泳','安全'],'NOAA JetStream · Rip Currents','https://www.noaa.gov/jetstream/ocean/rip-currents')
add(83,'tides','潮汐','Tides','自然与旅行','同一片海边，一天里会升起又退下。','海水周期性涨落主要受月球和太阳引力及地球自转影响。','月球和太阳对地球海水施加引力作用，地球自转让沿海地点依次经过潮汐隆起区域，因此海面会周期性升降。海岸形状也会改变潮汐表现。','每天潮汐的时间和幅度并不完全相同；不同海湾可能有不同潮型。','地球周围画出两处海水隆起，月球在一侧；岸边小屋随地球转动经历满潮和低潮。标签：月球引力｜海水隆起｜涨潮与退潮',['海洋','月球','地理'],'NOAA JetStream · Tides','https://www.noaa.gov/jetstream/ocean/tides')
add(84,'altitude-sickness','高原反应','Altitude Sickness','自然与旅行','到了高海拔，为什么走几步就气喘头痛？','海拔升高后气压降低，每次呼吸获得的氧气分压也随之降低。','高海拔空气中的氧气比例与低处大致相同，但气压更低，使吸入气体中的氧分压下降。身体需要时间适应，因此爬升过快时可能出现高原病症状。','严重头痛、意识改变或呼吸困难需要尽快下撤并寻求医疗帮助；不能靠硬撑适应。','山路海拔剖面：登山者从低处轻松走到高处开始气喘，旁边两格显示气压计读数随海拔降低。标签：海拔升高｜气压下降｜适应时间',['登山','气压','健康'],'CDC Yellow Book · High-Altitude Travel and Altitude Illness','https://wwwnc.cdc.gov/travel/yellowbook/2024/environmental-hazards-risks/high-altitude-travel-and-altitude-illness')
add(85,'wind-chill','风寒效应','Wind Chill','自然与旅行','温度一样，有风时人为什么觉得更冷？','风会加快皮肤表面热量散失，让裸露皮肤感觉更冷。','风寒效应描述风和低温共同作用下人体皮肤的冷感。风会带走皮肤附近较暖的空气层，使热量更快散失，体感温度因此下降。','风寒指数描述的是人体感受与冻伤风险，不会把实际空气温度变低。','同一位行人站在无风与强风两格：外套附近温暖空气层在风中被吹散，热量箭头变多，皮肤发凉。标签：皮肤暖空气层｜风带走热量｜体感更冷',['天气','体感','冬季'],'National Weather Service · Wind Chill','https://www.weather.gov/safety/cold-wind-chill-chart')
add(86,'snow-blindness','雪盲','Snow Blindness','自然与旅行','雪地刺眼不只因为白，紫外线也在反射。','雪面会反射紫外线，强烈照射可损伤眼睛表面并引起疼痛。','雪盲通常指紫外线引起的角膜光损伤。雪面对紫外线的反射会增加眼睛暴露，因此高海拔、长时间雪地活动时要保护双眼。','不只是“亮到睁不开眼”；眼痛、流泪和畏光等症状可能延迟出现，应及时寻求医疗建议。','雪山上太阳光照到雪面后多方向反射，戴有侧面防护的护目镜能遮挡部分紫外线；旁边画出眼睛受刺激的红色小符号。标签：紫外线｜雪面反射｜护眼',['雪地','紫外线','眼睛'],'WHO · Ultraviolet radiation: known health effects','https://www.who.int/news-room/questions-and-answers/item/radiation-the-known-health-effects-of-ultraviolet-radiation')
add(87,'glacial-landforms','冰川地形','Glacial Landforms','自然与旅行','山谷像被巨勺刮过，可能是冰川留下的。','移动的冰川夹带岩石，能侵蚀、搬运并堆积地表物质。','冰川在重力作用下缓慢流动，底部的岩石碎屑会磨蚀地面；冰体也能搬运和堆积物质，形成U形谷、冰碛等地貌。','不是所有宽阔山谷都由冰川形成；地貌通常需要结合岩层和其他地质证据判断。','山谷剖面三格：冰川填满V形河谷，底部刮蚀后形成宽底陡壁的U形谷，冰退后留下侧边冰碛。标签：冰川流动｜侵蚀｜U形谷',['地质','冰川','山谷'],'National Park Service · Glacial Geology','https://www.nps.gov/glac/learn/nature/glacial-geology.htm')

add(88,'banana-kick','香蕉球','Banana Kick','体育运动','球明明朝门边飞，半路却拐进球门。','旋转球带动周围气流不对称，空气作用力会让球的路径弯曲。','足球旋转时，球面带动周围空气流动；两侧气流速度和压力差会产生侧向作用力，使球的飞行轨迹弯曲。踢球部位和旋转方向会影响弯曲方向。','香蕉球的弯曲程度还受球速、转速、环境和球体状态影响；不能只靠一个踢球点保证结果。','球场俯视图：足球从右脚外侧旋转飞出，弧形轨迹绕过人墙弯向球门；画两侧气流箭头和旋转箭头。标签：旋转｜气流差｜弯曲轨迹',['足球','旋转','空气动力'],'FIFA · The physics behind Subri’s swerve','https://inside.fifa.com/news/the-physics-behind-subri-s-swerve-2860614')
add(89,'beat-the-offside-trap','反越位跑位','Beating the Offside Trap','体育运动','后卫往前一提，前锋为什么偏偏要等半拍？','进攻者在队友传球瞬间保持不越位，再冲向身后空间。','反越位跑位通常是针对防线前压：进攻者观察传球时机，在队友触球传球前不处于越位位置，传球瞬间再启动攻击身后空间。','有没有越位取决于队友触球传球的那一瞬和规则位置；跑动时机本身不能保证一定成功。','足球场三帧：防守线先前压；传球者触球时前锋仍与倒数第二名防守队员平齐；传出后前锋冲向身后接球。标签：防线前压｜传球瞬间｜向前启动',['足球','越位','跑位'],'IFAB · Law 11: Offside','https://backup.theifab.com/laws/latest/offside/')
add(90,'basketball-triple-threat','篮球三威胁','Triple Threat Position','体育运动','接球后先稳住，投、传、突都还来得及。','三威胁姿势让持球者准备好投篮、传球或突破。','篮球三威胁姿势通常是稳定的持球准备状态：双脚平衡、球受到保护，球员可以根据防守选择投篮、传球或运球突破。','它不是固定的违规动作或必胜招式；具体姿势会因球员、空间和防守情况改变。','球员在防守者前保持屈膝和护球姿势，三条清楚的箭头分别通向投篮、传球和突破。标签：投篮｜传球｜突破',['篮球','进攻','选择'],'FIBA · Basketball rules and coaching resources','https://www.fiba.basketball/documents')
add(91,'euro-step','欧洲步','Euro Step','体育运动','上篮前先跨向一边，再切向另一边。','欧洲步用连续变向步伐避开防守者，同时完成合法上篮脚步。','欧洲步通常在收球后通过左右变向跨步改变进攻路线，诱使防守者移动，再从另一侧完成上篮。成败取决于脚步时机、空间和适用规则。','合法脚步要依规则和收球时点判断；视觉上像“两步”不代表每种走法都合法。','篮球三帧俯视：防守者挡住正前方，持球人先向左跨步诱导，再向右跨步绕开，最后上篮。标签：假方向｜变向跨步｜绕开防守',['篮球','脚步','变向'],'FIBA · Basketball rules and coaching resources','https://www.fiba.basketball/documents')
add(92,'table-tennis-spin','乒乓球旋转','Table Tennis Spin','体育运动','球拍刷过球的方向，会改写球落台后的弹跳。','摩擦给球加入旋转，改变飞行与碰台后的反弹方向。','球拍与球之间的切向摩擦会让球旋转。旋转影响飞行轨迹；球接触球台或对手拍面后，反弹方向和速度也会变化。','看到球的弧线不总能直接判断旋转强弱，来球、球拍角度和击球速度也会影响结果。','三球对照：上旋球过网后下坠并向前弹，侧旋球落台后偏向一侧，下旋球弹起较低；画球自转箭头。标签：上旋｜侧旋｜下旋',['乒乓球','旋转','弹跳'],'International Table Tennis Federation · Laws of Table Tennis','https://www.ittf.com/handbook/')
add(93,'badminton-slice','羽毛球切球','Badminton Slice','体育运动','击球看着用力，球却像突然慢下来拐了方向。','拍面擦切羽毛球，会让飞行变慢并改变落点。','切球是在击球时让拍面斜擦球头或羽毛部分，使球旋转并改变飞行状态。羽毛球本身空气阻力大，切击后速度和轨迹会显得不寻常。','切球是否有效取决于触球点、拍面角度和伪装时机；不是所有“侧打”都产生相同效果。','羽毛球场侧视两格：正面击球直接飞向后场；斜擦球头后球速变慢、转向网前空档。标签：拍面擦切｜减速｜网前落点',['羽毛球','拍面','旋转'],'Badminton World Federation · Shuttle Time resources','https://shuttletime.bwfbadminton.com/')
add(94,'racing-line','赛车走线','Racing Line','体育运动','弯道里走外—内—外，通常能让转弯更顺。','通过拉大弯道半径，赛车能更平顺地通过弯心并加速出弯。','赛车走线是在赛道边界内选择转弯路径。外侧进入、接近弯心后驶向外侧，可以扩大转弯半径，但要结合连续弯道、抓地和出弯方向调整。','“外—内—外”不是每个弯的固定答案；赛道规则和后续弯道会改变最佳路线。','俯视赛道弯道：赛车从外侧入弯，经过内侧弯心，再向外侧出弯；与急促的小半径路线对照。标签：入弯｜弯心｜出弯',['赛车','弯道','驾驶'],'FIA · Driving and racing line guidance','https://www.fia.com/regulation/category/110')
add(95,'swimming-streamline','游泳流线型','Streamlining in Swimming','体育运动','蹬墙后伸直身体，阻力会小一些。','身体收紧成较小迎水面积，能减少水中阻力。','流线型姿势让身体沿前进方向伸展，头臂躯干尽量排列成稳定线条，减少迎水面积和扰动。蹬壁后的滑行常用于维持速度。','流线型不会消除阻力；姿势和泳姿不同，适用的滑行距离也不同。','泳池侧视对照：一名游泳者蹬壁后双臂夹耳、身体平直滑行，水流线较顺；另一人抬头屈腰，水流紊乱。标签：身体平直｜迎水面积小｜水流顺',['游泳','阻力','姿势'],'USA Swimming · Streamline and starts resources','https://www.usaswimming.org/coaches-learn-teach/coaches/education-certification')
add(96,'ski-carving','滑雪刻滑','Ski Carving','体育运动','把板刃立起来，雪板会沿弧线转弯。','立刃和身体压力让雪板弯曲，沿板刃切出弧形轨迹。','刻滑时滑雪者把雪板立刃并施加压力，雪板弯曲后沿刃线转弯，在雪面留下较干净的弧形轨迹。速度、雪质和坡度都会影响控制。','刻滑不等于把板倾得越多越好；失去平衡或在拥挤雪道上做大弯都可能危险。','雪道俯视两条轨迹：左边横着推雪形成宽滑痕，右边立刃后留下整齐弧形细线；人物重心位于弯内侧。标签：立刃｜板身弯曲｜弧形雪痕',['滑雪','雪板','转弯'],'U.S. Ski & Snowboard · Alpine skiing resources','https://www.usskiandsnowboard.org/sites/default/files/files-resources/files/2018/2019_FRE_CompGuide.pdf')
add(97,'marathon-pacing','马拉松配速','Marathon Pacing','体育运动','前半程跑得太快，后半程就可能一路追债。','合理配速把体力分配到整场比赛，避免过早透支。','马拉松配速是对全程速度和体力的安排。开跑过快会更早消耗可用能量并增加疲劳，稳定或按训练计划调整速度更有利于完成全程。','不存在人人适用的理想配速；训练、天气、路线和健康状况都要考虑。','赛道时间线：前半程冲得过快的跑者后半程速度明显下滑；另一条稳定配速线平稳到达终点。标签：前半程｜体力储备｜后半程',['跑步','马拉松','体能'],'World Athletics · Marathon pacing analysis','https://worldathletics.org/waendurancemedicine/news/an-investigation-on-world-majors-marathons-part-2-running-performance-analysis-of-amateur-runners')

add(98,'vacuum-insulation','保温杯真空层','Vacuum Insulation','居家与饮食','杯壁中间抽掉空气，热量就少了一条传递路。','真空夹层减少杯壁间的热传导和空气对流。','双层杯壁之间的真空大幅减少空气分子传递热量和对流；反射层还可减少热辐射。杯口、杯盖和结构连接处仍会传热。','真空层不是绝对隔热，也不能阻止所有热量通过杯口和杯盖流失。','保温杯剖面：双层不锈钢壁中间用浅色空隙表示真空，热量箭头在侧壁处中断，杯口仍有少量箭头穿过。标签：内壁｜真空层｜杯口传热',['保温','热传递','杯子'],'U.S. Department of Energy · Insulation','https://www.energy.gov/energysaver/insulation')
add(99,'refrigerator-cooling','冰箱制冷','Refrigeration Cycle','居家与饮食','冰箱不是制造冷气，而是把热搬到外面。','制冷剂循环蒸发吸热、压缩升温、冷凝放热，再回到冰箱内部。','压缩式冰箱通过制冷剂循环搬运热量：蒸发器从箱内吸热，压缩机提高制冷剂压力和温度，冷凝器再把热排到室内。','冰箱背面散出的热量加上压缩机消耗的能量，通常多于它从箱内搬出的热量。','冰箱循环箭头：箱内蒸发器吸热，压缩机把气体压热，背后冷凝器放热，节流后制冷剂回到箱内。标签：吸热｜压缩｜放热',['冰箱','制冷','热量'],'U.S. Department of Energy · Refrigerators and freezers','https://www.energy.gov/energysaver/refrigerators-and-freezers')
add(100,'air-conditioning-dehumidify','空调除湿','Air-Conditioning Dehumidification','居家与饮食','冷盘管上结露，房间里的水汽就少了一些。','空气经过低温盘管，水蒸气凝结成水滴后被排走。','制冷运行时，室内空气经过低于露点温度的蒸发器盘管，部分水蒸气凝结在盘管表面并排出。除湿与降温常同时发生。','空调的除湿能力取决于温湿度、气流和运行状态；它不等于独立除湿机的稳定控制。','空调剖面：潮湿暖空气流过冷盘管，蓝色水滴凝结后沿排水管离开，较凉较干空气回到房间。标签：湿空气｜冷盘管｜凝结水',['空调','湿度','冷凝'],'U.S. Department of Energy · Air conditioning','https://www.energy.gov/energysaver/air-conditioning')
add(101,'pressure-cooker','压力锅','Pressure Cooker','居家与饮食','锅里压力升高，水能在更高温度下沸腾。','密闭增压让水的沸点升高，食物可在更高温度下烹煮。','压力锅密闭加热后，内部压力上升。压力越高，水的沸点通常越高，因此锅内温度可高于常压沸水，加快某些食物的烹煮。','压力锅需要按说明操作并保持排气阀和密封部件畅通；高压容器不可擅自改造。','透明锅体剖面：蒸汽被密闭在锅内，压力表指针上升，水温刻度超过常压沸点；安全阀旁留出清晰位置。标签：蒸汽｜压力上升｜沸点升高',['烹饪','压力','温度'],'USDA · Cooking with a pressure cooker','https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/cooking-food')
add(102,'maillard-reaction','美拉德反应','Maillard Reaction','居家与饮食','面包表面变金黄，香味也是化学反应的一部分。','加热时还原糖与氨基化合物发生反应，生成褐色物质和风味分子。','美拉德反应是一系列发生在还原糖与氨基化合物之间的化学反应，常在加热食物时带来褐变和复杂香气。表面越干燥，温度越容易升高。','它不同于单纯糖的焦糖化；颜色和香味还受温度、时间、酸碱度和食材组成影响。','平底锅上两块面包：湿润时表面蒸汽多、颜色浅；表面水分减少后，糖和氨基化合物受热形成金褐色外壳并飘出香气线。标签：糖｜氨基化合物｜褐变与香气',['烹饪','化学','香味'],'Food Chemistry · The Maillard reaction in foods','https://pmc.ncbi.nlm.nih.gov/articles/PMC8166758/')
add(103,'microwave-heating','微波加热','Microwave Heating','居家与饮食','微波炉让食物里的水分子跟着电场来回转。','微波电场驱动极性分子转动，能量最终通过分子运动转成热。','微波炉中的交变电场会作用于水等极性分子，使其取向不断变化；分子与周围物质相互作用后，能量转化为热量。炉腔结构也会造成加热分布不均。','不是“微波只加热水”；食物成分和形状会影响升温，也可能留下冷热不均的区域。','微波炉内电场箭头来回变化，食物中的水分子跟着转动；中央和边缘出现不同温度斑块。标签：交变电场｜分子转动｜热量',['厨房','微波','电磁波'],'USDA FSIS · Microwave ovens and food safety','https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/microwave-ovens-and-food-safety')
add(104,'foam-stability','泡沫稳定性','Foam Stability','居家与饮食','打出的泡沫为什么有时很快就塌了？','液膜排液、气泡合并和气体扩散都会让泡沫逐渐消失。','泡沫由气泡和薄液膜组成。重力会让液体排出，邻近气泡可能合并，气体也会跨膜扩散；液体黏度和表面活性物质会改变稳定时间。','泡沫稳定性不能只看泡孔大小；配方、温度和搅拌方式都会影响结果。','透明杯中气泡随时间变化：底部液体逐渐增多，上部气泡变大并合并，最后泡沫变薄；旁边标出一层薄液膜。标签：薄液膜｜排液｜气泡合并',['食物','气泡','材料'],'Nature Education · Surface tension and foams','https://www.nature.com/scitable/knowledge/library/surface-tension-and-water-1440118/')
add(105,'noise-cancellation','主动降噪','Active Noise Cancellation','居家与饮食','耳机放出一段反向声波，低频噪声会弱一些。','麦克风采样环境声，耳机生成相位相反的声波与之抵消。','主动降噪系统用麦克风检测环境声音，再播放经过处理的反相信号。两列声波在耳边叠加后，部分频率的声压会减小。','它不能让所有频率和所有位置完全静音；高频、突发声和佩戴漏音仍可能听见。','耳机剖面两条相反相位的声波在耳道处相遇，波峰和波谷部分抵消；远处尖锐短声仍留下一小段波形。标签：环境噪声｜反相声波｜部分抵消',['声音','耳机','波'],'NASA · Noise control and active noise cancellation','https://www.nasa.gov/centers-and-facilities/armstrong/quieting-the-supersonic-x-59/')
add(106,'dew-point-condensation','露点与冷凝','Dew Point and Condensation','居家与饮食','冰饮杯外的水珠，来自空气里的水汽。','空气冷却到露点附近时，水蒸气会在冷表面凝结成液滴。','空气中的水蒸气含量与温度有关。空气接触冰杯等冷表面后降温，达到露点时水汽凝结成水滴，附着在杯外。','杯外水滴通常不是从杯里渗出来；空气湿度越高，冷表面越容易出现冷凝。','炎热房间里一只冰饮杯外壁凝出水滴，放大镜显示看不见的水汽在冷杯表面变成液滴；旁边画一辆雨天起雾的车窗，说明同样的冷凝。标签：空气水汽｜冷表面｜凝结水滴',['湿度','天气','冷凝'],'NOAA JetStream · Dew point','https://www.noaa.gov/jetstream/atmosphere/dew-point')
add(107,'siphon','虹吸现象','Siphon','居家与饮食','一根装满水的弯管，能把水从高处引到低处。','连续液柱在重力和压强差作用下，从较高液面流向较低出口。','虹吸需要管中有连续液体，并让出口低于源液面。重力使下降段液柱向下，造成压强差，液体于是持续越过高处流向低处。','虹吸不是“高处吸水”；若液柱中断、漏气或出口不够低，流动就可能停止。','透明水槽与弯管剖面：管子先装满水，入口浸在高水位，出口低于液面，蓝色液流跨过管顶向下流出。标签：高水位｜连续液柱｜低处出口',['水','压强','物理'],'Harvard Natural Sciences Lecture Demonstrations · Siphon','https://sciencedemonstrations.fas.harvard.edu/presentations/siphon')

add(108,'anchoring-effect','锚定效应','Anchoring Effect','心理与生活','先看到的数字，会悄悄影响后来的估价。','判断时过度依赖最先出现的数值，再围绕它调整。','锚定效应指人在估计或判断时，受到先前数值影响；即便这个数与问题无关，后续调整仍可能不够充分。','它描述的是常见判断偏差，不代表每个人都会被同一个数字影响同样多。','两位顾客估同一只背包：一人先看见标价800，另一人先看见标价200，随后各自对折扣后的合理价格估计不同。标签：先出现的数字｜调整｜后续估价',['判断','价格','心理'],'Tversky & Kahneman · Judgment under Uncertainty: Heuristics and Biases','https://pubmed.ncbi.nlm.nih.gov/17835457/')
add(109,'loss-aversion','损失厌恶','Loss Aversion','心理与生活','丢掉一百元的难受，常比捡到一百元的开心更强。','同等大小的损失和收益，心理影响往往并不对称。','损失厌恶描述人们常常更在意损失而非相同大小的收益。它会影响风险选择、价格判断和对现有资源的态度。','强弱因人、情境和参照点而变；它不是人人都固定遵循的倍数定律。','天平两侧各放100元：损失一侧的情绪云更大，获得一侧较小；同一个人面对两个选择。标签：损失100元｜获得100元｜感受不对称',['决策','风险','行为经济'],'Kahneman & Tversky · Prospect Theory','https://doi.org/10.2307/1914185')
add(110,'peak-end-rule','峰终定律','Peak-End Rule','心理与生活','回忆一段经历，最强烈和最后的时刻很重要。','人们回顾体验时，常受最强烈时刻和结尾影响。','峰终定律描述回顾性评价的一种倾向：人们对一段体验的记忆，可能更受情绪高峰和结束时刻影响，而非简单计算全过程。','这是实验中观察到的记忆模式，不能用来预测每个人每次经历的评价。','三段旅程时间线：中间最开心的峰值和结束时刻画得突出，其他普通时刻淡化；下方显示回忆评价受两处影响。标签：过程｜情绪高峰｜结束时刻',['记忆','体验','心理'],'Kahneman et al. · When More Pain Is Preferred to Less: Adding a Better End','https://pmc.ncbi.nlm.nih.gov/articles/PMC3012151/')
add(111,'confirmation-bias','确认偏误','Confirmation Bias','心理与生活','支持自己猜想的证据，往往更容易被看见。','搜集和解读信息时，人容易偏向支持既有判断的部分。','确认偏误是指人们更容易注意、寻找或相信与现有看法一致的信息，同时较少关注相反证据。它可能让错误信念在筛选信息中持续。','看到一条相符证据并不自动代表有偏误；评估时还要看信息质量和反例。','主人公相信某家店最好：只把好评放进篮子，把差评绕过去；另一位朋友把正反评价都放到天平上。标签：原有看法｜支持信息｜被忽略的反例',['判断','信息','心理'],'Wason · On the failure to eliminate hypotheses in a conceptual task','https://doi.org/10.1080/17470215808416280')
add(112,'endowment-effect','禀赋效应','Endowment Effect','心理与生活','同一只杯子，拥有以后会觉得更舍不得卖。','仅仅因为已拥有某物，人对它的估值可能上升。','禀赋效应是指人们对已拥有物品的估值常高于拥有前的支付意愿。拥有状态会改变比较基准，使放弃物品像一种损失。','它不是所有商品和所有交易中的固定规律；经验、交易成本与市场价格都可能改变结果。','同款马克杯在两位顾客面前：未拥有者写下愿付价，刚得到杯子的人写下愿卖价，后者通常更高。标签：拥有之前｜已经拥有｜放弃像损失',['购物','所有权','行为经济'],'Kahneman, Knetsch & Thaler · Experimental Tests of the Endowment Effect','https://www.journals.uchicago.edu/doi/abs/10.1086/261737')
add(113,'decoy-effect','诱饵效应','Decoy Effect','心理与生活','多出一个明显较差的选项，可能让另一款显得更划算。','与某选项相似却在关键属性上更差的诱饵，会改变相对偏好。','诱饵效应指选择集合加入一个不对称占优的选项后，人们对另一个选项的偏好可能提高。比较对象改变了相对优势感。','增加选项不保证偏好一定按同一方向变化；设计、属性和人群都会影响结果。','咖啡菜单两选项先出现：小杯20元、大杯30元；加入一个中杯28元后，旁边对照“更贵但略小”的诱饵，让大杯的相对优势变明显。标签：原选项｜诱饵｜相对更划算',['消费','选择','价格'],'Huber, Payne & Puto · Adding Asymmetrically Dominated Alternatives','https://doi.org/10.1086/208515')
add(114,'mental-accounting','心理账户','Mental Accounting','心理与生活','工资、红包和退款，明明都是钱却被分开花。','人们会在脑中把钱按来源、用途或时间分进不同账户。','心理账户是人们组织和评估金钱的一种方式。钱的来源或用途标签会影响支出决定，即使这些钱在客观上可以互换。','心理账户是描述判断方式的概念；做预算时分类也可能有助于管理，不应简单等同于错误。','同一人的钱包分成“工资、红包、退款”三个小格：同样金额在不同格子里，被决定用于不同消费；旁边画同等的钱币。标签：钱的来源｜心理分类｜不同花法',['消费','预算','行为经济'],'Thaler · Mental Accounting and Consumer Choice','https://pubsonline.informs.org/doi/fpi/10.1287/mksc.4.3.199')
add(115,'framing-effect','框架效应','Framing Effect','心理与生活','说“存活九成”和说“死亡一成”，感受可能不同。','同一结果换一种表述方式，可能改变人们的选择。','框架效应指相同或等价的信息以不同方式呈现时，人们的判断与偏好可能改变。描述为收益或损失，会影响决策者如何感受风险。','表述不同不一定改变真实概率；判断时应先把不同说法转换成同一数量尺度。','一张医疗选择卡左右并排：“100人中90人存活”和“100人中10人死亡”，下方指向同一组100个圆点，展示等价数字却触发不同感受。标签：收益说法｜损失说法｜同一组人数',['表达','风险','选择'],'Tversky & Kahneman · The Framing of Decisions and the Psychology of Choice','https://doi.org/10.1126/science.7455683')
add(116,'discount-stacking','折扣叠加','Stacked Discounts','心理与生活','七折再打八折，不等于直接打五折。','连续折扣按剩余价格逐次计算，不能把折扣比例直接相加。','先打七折表示支付原价的70%；再打八折是在折后价上支付80%。两步相乘为原价的56%，所以总优惠是44%。','优惠券、满减和税费可能有各自顺序与条件，需按结账规则逐项计算。','原价100元的商品经两个折扣：100→70→56，旁边错误算法100→50打叉。标签：原价100｜先乘70%｜再乘80%',['购物','打折','数学'],'FTC · Shopping and pricing guidance','https://consumer.ftc.gov/articles/shopping-online')
add(117,'unit-pricing','单位价格','Unit Pricing','心理与生活','包装看着更大，不代表每克更便宜。','把价格换算到相同重量或容量单位，才能公平比较。','单位价格把商品价格换算成每克、每升或每件的价格，便于比较不同规格的商品。大包装可能单价更低，也可能更贵。','促销、品质、保质期和实际用量也重要；单价低不自动意味着更划算。','货架两包米：小袋5千克卖30元，大袋8千克卖44元；旁边计算每千克价格并标出大袋的单价更低。标签：总价｜重量｜每千克价格',['超市','价格','比较'],'USDA · Unit pricing information','https://www.ams.usda.gov/rules-regulations/packers-and-stockyards/programs/unit-pricing')

add(118,'foley-sound','电影拟音','Foley Sound','影音与错觉','电影里没有的脚步声，常是后来“做”出来的。','拟音师用物件和动作同步录制声音，补上画面的细节。','拟音是在后期制作中，为画面中的脚步、衣料、道具等动作现场制作和录制匹配声音。声音能让虚构场景更具体，也能帮助塑造节奏和情绪。','拟音不等于所有电影声音；对白、音乐、环境声和音效通常由不同素材与工序组成。','录音棚里拟音师跟着银幕人物走路，用鞋踩碎石录下脚步；旁边播放声音波形同步贴在画面时间线上。标签：画面动作｜现场制作｜同步声音',['电影','声音','后期'],'Columbia University Film Glossary · Foley','https://filmglossary.ccnmtl.columbia.edu/term/foley/')
add(119,'film-24fps','电影24帧','24 Frames per Second','影音与错觉','一秒放出24张画面，眼睛就把它看成连续运动。','快速连续呈现静止画面，产生平滑运动的知觉效果。','每秒24帧是电影中长期使用的一种帧率。连续静帧快速呈现时，观众通常感知为连续动作，但清晰度和运动观感还受快门、投影与显示方式影响。','24帧不是唯一帧率，也不表示所有屏幕都按24次闪烁；电影帧率和刷新率不同。','电影胶片连续格子里有24张不同姿势的小跑步者，一秒通过放映机后在银幕上看成连续奔跑。标签：静止画格｜每秒24帧｜连续运动',['电影','帧率','视觉'],'Library of Congress · Motion picture frame rate glossary','https://www.loc.gov/catdir/cpso/app-glos.html')
add(120,'green-screen','绿幕抠像','Green-Screen Compositing','影音与错觉','演员站在绿布前，后面可以换成火星。','后期按颜色选出绿幕区域，再合成另一段背景影像。','色键抠像会识别画面中指定颜色，将其区域设为透明，再放入另一层图像。绿幕颜色通常避开人物主体常见肤色和服装色。','绿幕不能自动解决头发边缘、阴影、反光和绿色溢色；布光与边缘处理也很重要。','摄影棚里演员站在均匀绿色背景前，后期步骤把绿幕区域变透明并放入火星基地；用图层剖面显示前景和背景。标签：绿幕｜颜色抠除｜新背景',['电影','特效','合成'],'Adobe · Chroma key and green screen','https://helpx.adobe.com/premiere-pro/using/ultra-key-effect.html')
add(121,'stage-illusion','舞台视错觉','Stage Illusion','影音与错觉','舞台上的人忽然变大，可能只是距离和视角在配合。','舞台道具、灯光与观众视点能共同制造大小和空间错觉。','舞台错觉常利用透视、遮挡、光线、活动布景和观众视角，让实际物体看起来更大、更近或突然出现。','不同舞台效果原理不同；不要把所有变形和消失都归因于一种“魔法镜子”。','小剧场侧视图：近处矮道具和远处高道具从观众席看起来同高，演员沿暗处移动制造突然消失；标注观众唯一视点。标签：观众视点｜近处道具｜远处布景',['舞台','透视','表演'],'Victoria and Albert Museum · Theatre and performance collection','https://www.vam.ac.uk/collections/theatre-and-performance')
add(122,'ebbinghaus-illusion','艾宾浩斯错觉','Ebbinghaus Illusion','影音与错觉','一样大的圆，周围圆圈不同，中心看起来就变了。','周围参照物的大小会影响人们对中心圆大小的判断。','艾宾浩斯错觉常用中心圆周围的一圈圆作为参照：被较小圆包围的中心圆看起来偏大，被较大圆包围的中心圆看起来偏小，尽管中心圆实际同大。','错觉强度会受到圆的间距、大小和观看条件影响；不是所有视觉任务都产生同样效果。','左右两组中心蓝圆完全同大：左边被小圈包围显得大，右边被大圈包围显得小；附小尺标确认中心圆相同。标签：小周围圆｜中心圆｜大周围圆',['视觉','错觉','参照'],'Acta Psychologica · The Ebbinghaus illusion','https://www.sciencedirect.com/science/article/pii/S0001691817304626')
add(123,'motion-perception','视觉暂留与运动知觉','Motion Perception','影音与错觉','逐张翻动画片，静止画纸也能变成奔跑的人。','快速更换相似画面，会让大脑感受到连续运动。','电影、动画和翻页小书由一系列静止画面组成。画面以一定速度变化时，视觉系统把它们组织为运动；运动感不是一张静态图自身移动。','“视觉暂留”不是解释所有动态视觉现象的完整答案；运动知觉还涉及时间整合和神经处理。','翻页小书左侧每张纸画小球稍移一点，快速翻动后右侧出现连续弹跳轨迹；旁边分解为多个静止帧。标签：静止画格｜快速变化｜连续运动感',['视觉','动画','大脑'],'NCBI Bookshelf · Motion perception','https://www.ncbi.nlm.nih.gov/books/NBK10991/')
add(124,'shepard-tone','谢泼德音调','Shepard Tone','影音与错觉','音阶听起来一直往上爬，音高却像没有尽头。','多个相隔八度的音同步渐强渐弱，制造循环上升的错觉。','谢泼德音调由多个相隔八度的音叠加组成。随着音阶向上移动，高音和低音逐渐淡入淡出，使听者感到音高不断上升却回到起点。','这是一种听觉错觉，不代表声音的实际频率无限上升。','钢琴键盘上叠着三条相隔八度的音阶：最上方高音逐渐淡出，下方新音渐强；听者头顶画循环向上的箭头。标签：多组八度｜渐强与渐弱｜循环上升感',['音乐','声音','错觉'],'JASA · Circularity in Judgments of Relative Pitch','https://pubs.aip.org/asa/jasa/article-abstract/36/12/2346/721348/Circularity-in-Judgments-of-Relative-Pitch?redirectedFrom=fulltext')
add(125,'stereo-localization','立体声定位','Stereo Localization','影音与错觉','两个耳朵听到的细微差别，能帮你判断声音从哪来。','左右耳的到达时间和强度差异，为声音方向提供线索。','听者可利用声音到达两耳的时间差和强度差判断水平位置；耳廓与环境反射也提供额外线索。耳机左右声道差异会影响听到的方向感。','立体声定位不是只靠左右音量；前后、高低和真实空间还依赖其他听觉线索。','声音源在听者左侧：声波先到左耳，右耳稍晚且较弱；转到正前方时两耳差值变小。标签：左耳先到｜右耳稍晚｜方向判断',['声音','耳朵','空间'],'PMC · Auditory localization mechanisms','https://pmc.ncbi.nlm.nih.gov/articles/PMC3985897/')
add(126,'odd-meter','变拍子','Changing Meter','影音与错觉','这段音乐忽然多一拍，舞步为什么会绊一下？','每小节拍数或重音分组改变，节奏循环会重新排列。','拍号和节奏重音帮助听者感知规律。变拍子会改变每小节的拍数或分组方式，使音乐的重音循环与此前不同。','节拍复杂不等于速度更快；变拍子也不只是随机增加一拍。','鼓手按4拍循环演奏后切换为3拍，再回到4拍；用色块清晰画出每小节重音位置和舞者的步伐变化。标签：四拍｜三拍｜重音改变',['音乐','节奏','舞蹈'],'Oxford Music · Meter and rhythm','https://www.oxfordmusiconline.com/grovemusic')
add(127,'stage-perspective','舞台透视','Stage Perspective','影音与错觉','舞台尽头的门看起来更远，可能只是布景变窄了。','把侧墙和道具向舞台后方收窄，观众会感到空间更深。','舞台透视利用斜向布景、尺寸递减和灯光层次制造深度。观众从固定视点观看时，较小的远端结构会被理解为更远的空间。','这种效果依赖观众位置；从侧面看，布景可能明显不对称。','剧场俯视对照：平行侧墙一格显得浅，逐渐收窄的侧墙和变小的窗户另一格看起来更深；标出观众席视线。标签：观众视点｜逐渐收窄｜空间更深',['舞台','布景','透视'],'University of Oklahoma · Introduction to Film and TV','https://open.library.okstate.edu/introfilmtv/part/editing/')

add(128,'mirror-reversal','镜子里的左右颠倒','Mirror Reversal','物理科学','镜子把前后翻过去了，为什么我们总说左右反了？','平面镜反转的是前后方向；左右互换来自我们对镜像的比较方式。','平面镜会把垂直镜面的前后方向反射，不会直接交换左右或上下。我们想象自己转身与镜中人面对面时，才会觉得左右位置互换。','镜像的方向关系取决于坐标参照；不是镜子主动识别左右再翻转。','镜子前的探险者举起右手，镜中影像也在画面对应侧抬手；转身模型显示前后轴反向而左右轴保持。标签：镜面｜前后反转｜转身比较',['镜子','光学','空间'],'American Journal of Physics · Mirror reversal and reflections','https://pubmed.ncbi.nlm.nih.gov/10780031/')
add(129,'bicycle-stability','自行车不易倒的原因','Bicycle Self-Stability','体育运动','骑起来时车身会自己修正一点方向，但并不只靠陀螺效应。','车轮、前叉几何和转向共同影响自行车的动态稳定性。','自行车的稳定性涉及车轮旋转、前叉几何、转向与骑手动作等多个因素。实验表明，不能把“不倒”简单归结为车轮陀螺效应或前轮自动摆正中的任何一个。','自行车在不同速度和设计下表现不同；转弯时仍需要骑手控制重心与方向。','对照两辆可自稳实验自行车：一辆有反向旋转轮仍可稳定，另一辆前叉几何改变却仍能平衡；旁边骑手轻微转向修正。标签：车轮｜前叉几何｜转向修正',['自行车','平衡','力学'],'Science · Self-stability of a bicycle','https://pubmed.ncbi.nlm.nih.gov/21493856/')
add(130,'airplane-ear-pressure','飞机起降耳压不适','Airplane Ear Pressure','自然与旅行','飞机下降时，耳朵闷住是内外压力暂时没平衡。','外界气压变化时，中耳需要通过咽鼓管逐步调节压力。','飞机爬升或下降时舱内气压变化，中耳与外界之间出现压力差。咽鼓管打开后可让压力逐渐平衡，于是耳闷感减轻。','持续耳痛、感冒或其他耳鼻喉问题可能增加不适；症状严重时咨询医疗专业人士。','飞机下降时舱压计上升，旅客中耳两侧压力暂不平衡；吞咽动作打开咽鼓管，压力箭头逐渐相等。标签：舱压变化｜咽鼓管｜压力平衡',['飞行','耳朵','压力'],'FAA · Aeronautical Information Manual · Middle ear and sinus problems','https://www.faa.gov/air_traffic/publications/atpubs/aim_html/chap8_section_1.html')
add(131,'shelf-eye-level','超市视线高度陈列','Eye-Level Shelf Placement','心理与生活','同一排商品，放在眼前的更容易先被看见。','陈列位置影响商品被注意到的机会，但不决定每次购买。','货架的高度和位置会影响商品在购物者视线中的显著程度。研究发现，顾客会受陈列位置和包装等线索影响，但品牌选择还由价格、偏好和需求共同决定。','“放在视线高度必然卖最多”过于绝对；不同人身高、购物目标和门店布局都会改变结果。','超市货架正面图：同类麦片包装分别放在低层、视线层和高层，一位顾客视线停在中层但仍能选择其他层。标签：低层｜视线高度｜高层',['超市','陈列','消费'],'Journal of Marketing · Shelf placement and product choice','https://journals.sagepub.com/doi/10.1177/0022243721998375')

